create extension if not exists pgcrypto;
create type document_type as enum ('curriculum','transcript');
create type document_status as enum ('uploaded','extracting','review_needed','ready','failed');
create type requirement_type as enum ('required_course','elective_credit','total_credit');
create type match_type as enum ('automatic','manual');
create type match_status as enum ('confirmed','needs_review');

create table public.workspaces (id uuid primary key default gen_random_uuid(), anonymous_token_hash text not null unique, expires_at timestamptz not null, created_at timestamptz not null default now());
create table public.documents (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, type document_type not null, file_path text not null, file_name text not null, mime_type text not null check (mime_type in ('application/pdf','image/jpeg','image/png')), status document_status not null default 'uploaded', created_at timestamptz not null default now());
create table public.document_extractions (id uuid primary key default gen_random_uuid(), document_id uuid not null references public.documents(id) on delete cascade, raw_extraction_json jsonb not null, confidence numeric(4,3) not null check (confidence between 0 and 1), extraction_version text not null, created_at timestamptz not null default now());
create table public.courses (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, code text not null, name_th text, name_en text, credits numeric(4,1) not null check (credits > 0), grade text, term text, year integer, source text not null check (source in ('transcript','manual')), verified_by_user boolean not null default false, created_at timestamptz not null default now());
create table public.degree_requirements (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, category_name text not null, requirement_type requirement_type not null, required_course_code text, required_course_name text, minimum_credits numeric(5,1), prerequisite_data jsonb not null default '[]'::jsonb, source text not null check (source in ('curriculum','manual')), verified_by_user boolean not null default false, created_at timestamptz not null default now());
create table public.course_matches (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, course_id uuid not null references public.courses(id) on delete cascade, degree_requirement_id uuid not null references public.degree_requirements(id) on delete cascade, match_type match_type not null, confidence numeric(4,3) not null check (confidence between 0 and 1), status match_status not null default 'needs_review', unique(course_id, degree_requirement_id));
create table public.study_plans (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, name text not null, academic_term text not null, academic_year text not null, created_at timestamptz not null default now());
create table public.planned_courses (id uuid primary key default gen_random_uuid(), study_plan_id uuid not null references public.study_plans(id) on delete cascade, course_code text not null, course_name text not null, credits numeric(4,1) not null check (credits > 0), section text, instructor text, notes text, expected_grade text, source text not null check (source in ('requirement','manual')));
create table public.planner_meetings (id uuid primary key default gen_random_uuid(), planned_course_id uuid not null references public.planned_courses(id) on delete cascade, weekday smallint not null check (weekday between 0 and 6), start_time time not null, end_time time not null, check (end_time > start_time));
create table public.grade_scenarios (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, study_plan_id uuid references public.study_plans(id) on delete set null, name text not null, description text, created_at timestamptz not null default now());
create table public.grade_scenario_courses (id uuid primary key default gen_random_uuid(), grade_scenario_id uuid not null references public.grade_scenarios(id) on delete cascade, planned_course_id uuid references public.planned_courses(id) on delete cascade, course_code text not null, credits numeric(4,1) not null, expected_grade text not null);
create table public.workspace_deletion_jobs (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, scheduled_for timestamptz not null, completed_at timestamptz, created_at timestamptz not null default now());
create index on public.documents(workspace_id, created_at desc); create index on public.courses(workspace_id, code); create index on public.degree_requirements(workspace_id, category_name); create index on public.study_plans(workspace_id, created_at desc); create index on public.workspace_deletion_jobs(scheduled_for) where completed_at is null;
alter table public.workspaces enable row level security; alter table public.documents enable row level security; alter table public.document_extractions enable row level security; alter table public.courses enable row level security; alter table public.degree_requirements enable row level security; alter table public.course_matches enable row level security; alter table public.study_plans enable row level security; alter table public.planned_courses enable row level security; alter table public.planner_meetings enable row level security; alter table public.grade_scenarios enable row level security; alter table public.grade_scenario_courses enable row level security; alter table public.workspace_deletion_jobs enable row level security;
-- No browser role policies: Route Handlers use the service role after workspace-token verification.
insert into storage.buckets (id, name, public) values ('private-documents','private-documents',false) on conflict (id) do update set public=false;
